"""The pane API list (`pane_api/pane_api.json`) as the server's Python enums and caps and the
dashboard's TypeScript twin."""

from __future__ import annotations

import json
import re
import textwrap

from ..pane_api import PaneApi, PaneApiName
from ..probe_contracts import Contracts
from .typescript import member_key

SOURCE = "contracts/probe_contracts/pane_api/pane_api.json"
WIDTH = 100

_PY_HEADER = (
    f"# GENERATED by `python -m probe_contracts.codegen` from {SOURCE}.\n"
    "# Do not edit: change the list there and rerun.\n"
)
_TS_HEADER = (
    f"// GENERATED by `python -m probe_contracts.codegen` from {SOURCE}.\n"
    "// Do not edit: change the list there and rerun.\n"
)

#: (class name, the list's field, the class doc), in the order both targets write them.
_ENUMS = (
    ("PaneSource", "data_calls", "A recipe entry's source kind: `PROBE.<value>('<recipe id>')` reads one."),
    ("PaneFileCall", "file_calls", "`PROBE.<value>(file)`: a file read through the host bridge."),
    ("PaneFileError", "file_errors", "What a rejected file call's error says."),
    ("PanePageCall", "page_calls", "`PROBE.<value>(...)`: a call that reads no recipe entry and no file."),
    ("PaneOpenRef", "open_refs", "The one key of a `PROBE.open` ref: what it opens."),
    ("PaneOpenError", "open_errors", "What a refused `PROBE.open` rejects with."),
    ("PaneSourceState", "states", "A resolved entry's `state`."),
    ("PanePartialReason", "reasons", "Why a resolved entry is `partial`."),
    ("PaneCheckStatus", "check_statuses", "What the render check at push answered."),
    ("PaneCheckState", "check_states", "A state the render check draws the pane in."),
)


def _to_snake(name: str) -> str:
    """`onData` -> `on_data`: a camelCase JS name as the member's words (the value stays as is)."""
    return re.sub(r"(?<=[a-z0-9])(?=[A-Z])", "_", name).lower()


def _wrap(text: str, prefix: str) -> str:
    lines = textwrap.wrap(text, WIDTH - len(prefix), break_long_words=False, break_on_hyphens=False)
    return "".join(f"{prefix}{line}\n" for line in lines)


def _render_python_enum(name: str, doc: str, members: tuple[PaneApiName, ...]) -> str:
    body = "".join(
        _wrap(m.doc, "    #: ") + f"    {_to_snake(m.name).upper()} = {json.dumps(m.name)}\n" for m in members
    )
    return f"\n\nclass {name}(StrEnum):\n    \"\"\"{doc}\"\"\"\n\n{body}"


def render_pane_api_python(contracts: Contracts) -> str:
    api = contracts.pane_api or PaneApi.load()
    enums = "".join(_render_python_enum(name, doc, getattr(api, field)) for name, field, doc in _ENUMS)
    caps = "".join(_wrap(c.doc, "#: ") + f"{c.name.upper()} = {c.value}\n" for c in api.caps)
    return (
        _PY_HEADER
        + f'"""{textwrap.fill(api.doc, WIDTH - 4, break_long_words=False)}\n"""\n\n'
        + "from __future__ import annotations\n\nfrom enum import StrEnum\n\n"
        + "#: The recipe's `runs` value that means \"the runs in view\".\n"
        + f"PANE_RUN_SCOPE = {json.dumps(api.run_scope)}\n"
        + enums
        + "\n\n"
        + caps
    )


def _render_typescript_enum(name: str, doc: str, members: tuple[PaneApiName, ...]) -> str:
    body = "".join(
        _wrap(m.doc, "  // ") + f"  {member_key(_to_snake(m.name))}: {json.dumps(m.name)},\n" for m in members
    )
    return (
        f"\n/** {doc} */\nexport const {name} = {{\n{body}}} as const;\n"
        f"export type {name} = (typeof {name})[keyof typeof {name}];\n"
    )


def _to_camel(name: str) -> str:
    head, *rest = name.split("_")
    return head + "".join(part.capitalize() for part in rest)


def render_pane_api_typescript(contracts: Contracts) -> str:
    api = contracts.pane_api or PaneApi.load()
    enums = "".join(_render_typescript_enum(name, doc, getattr(api, field)) for name, field, doc in _ENUMS)
    caps = "".join(_wrap(c.doc, "  // ") + f"  {_to_camel(c.name)}: {c.value},\n" for c in api.caps)
    return (
        _TS_HEADER
        + "\n"
        + _wrap(api.doc, "// ")
        + "\n/** The recipe's `runs` value that means \"the runs in view\". */\n"
        + f"export const PANE_RUN_SCOPE = {json.dumps(api.run_scope)};\n"
        + enums
        + "\n/** The caps the server and the frame both hold. */\n"
        + f"export const PANE_CAPS = {{\n{caps}}} as const;\n"
    )
